                    <tr><td colspan="2"><em>No test details available</em></td></tr>
                  {{- end -}}
                </table>
              </td>
            </tr>
          {{- end -}}
        {{- end -}}
      {{- end -}}

      {{- /* Stable channel tests */ -}}
      {{- range $comp, $items := $grouped -}}
        {{- /* Sort by component version descending for stable tests */ -}}
        {{- $stable_items := slice -}}
        {{- range $items -}}
          {{- $version := index .Params "meshery-component-version" -}}
