            {{- $status_class = "status-partial" -}}
          {{- else if eq $status "failing" -}}
            {{- $status_class = "status-failing" -}}
          {{- end -}}
          <tr style="visibility: hidden; display: none;" class="test-details stable stable_visible" onclick="toggle_visibility('{{ $comp }}-stable');">
            <td class="{{ $status_class }}">{{ index .Params "timestamp" }}</td>
            <td style="white-space:nowrap;"><a href="https://github.com/meshery/meshery-{{ index .Params "service-mesh" | lower }}">{{ $comp }}</a></td>
            <td><a href="https://github.com/meshery/meshery-{{ index .Params "service-mesh" | lower }}/releases/tag/{{ index .Params "meshery-component-version" }}">{{ index .Params "meshery-component-version" }}</a></td>
            <td><a href="https://github.com/meshery/meshery/releases/tag/{{ index .Params "meshery-server-version" }}">{{ index .Params "meshery-server-version" }}</a></td>
            {{- $service_mesh := index .Params "service-mesh" | lower -}}
            {{- $adapter_page := site.GetPage (printf "extensions/adapters/%s" $service_mesh) -}}
            <td style="white-space:nowrap;"><img style="height: 2rem; vertical-align: text-bottom; margin-right: 8px;" src="{{ printf "project/compatibility-matrix/images/service-meshes/%s.svg" $service_mesh | relURL }}" />{{ if $adapter_page }}<a href="{{ $adapter_page.RelPermalink }}">{{ index .Params "service-mesh" }}</a>{{ else }}{{ index .Params "service-mesh" }}{{ end }}</td>
            <td>{{ index .Params "service-mesh-version" }}</td>
          </tr>
          <tr class="hidden-details" id="{{ $comp }}-stable" style="visibility:hidden; display:none;">
            <td colspan="2" class="details">
              <i>Platform:</i>
              <ul style="margin: 5px 0;">
                <li><img style="height: 1rem; vertical-align: text-bottom;" src="{{ "project/compatibility-matrix/images/service-meshes/kubernetes-icon-color.svg" | relURL }}" /> {{ index .Params "k8s-distro" | default "Unknown" }} {{ index .Params "k8s-version" | default "" }}</li>
              </ul>
            </td>
            <td colspan="4" class="details">
              <i>Test results:</i>
              <table style="border:0; margin-top: 5px;">
                {{- if index .Params "tests" -}}
                  {{- range $pod, $status := index .Params "tests" -}}
                    {{- $test_icon := "project/compatibility-matrix/images/service-meshes/passing.svg" -}}
                    {{- if eq (trim $status " ") "Running" -}}
                      {{- $test_icon = "project/compatibility-matrix/images/service-meshes/passing.svg" -}}
                    {{- else -}}
                      {{- $test_icon = "project/compatibility-matrix/images/service-meshes/failing.svg" -}}
                    {{- end -}}
                    <tr style="background-color: transparent;">
                      <td><img style="height: 24px; width: 24px; margin-right: 8px;" src="{{ $test_icon | relURL }}" alt="Test Status" /></td>
                      <td>{{ $pod }}</td>
