<script>
  (function() {
    function injectToggleButton(li, icon, position, extraClass) {
      // Only process sections that actually have children (ul exists)
      var ul = li.querySelector(":scope > ul");
      var a = li.querySelector(":scope > a.td-sidebar-link");
      if (!a || !ul) return;
      
      if (li.querySelector(':scope > .sidebar-section-flex-wrapper')) return;
      
      var btn = document.createElement("button");
      btn.className = "sidebar-section-toggle " + (extraClass || "");
      btn.setAttribute("aria-label", "Toggle section");
      btn.innerHTML = icon;
      btn.onclick = function(e) {
        e.preventDefault();
        
        var $ul = $(ul);
        var childLis = ul.querySelectorAll(":scope > li");
        var isClosed = childLis.length > 0 && !childLis[0].classList.contains("show");
        
        if (isClosed) {
          $ul.hide();
          childLis.forEach(function(childLi) {
            childLi.classList.add("show");
          });
        }
        
        $ul.slideToggle(400, function() {
          if ($ul.css("display") === "none") {
            childLis.forEach(function(childLi) {
              childLi.classList.remove("show");
            });
            $ul.css("display", "");
          }
        });

        li.classList.toggle("active-path");
      };
      
      var wrapper = document.createElement("div");
      wrapper.className = "sidebar-section-flex-wrapper";
      a.parentNode.insertBefore(wrapper, a);
      
      if (position === "after") {
        wrapper.style.justifyContent = "space-between";
        wrapper.appendChild(a);
        wrapper.appendChild(btn);
      } else {
        wrapper.appendChild(btn);
        wrapper.appendChild(a);
      }
    }

    var caretIcon = '<svg class="caret-icon" viewBox="0 0 16 16" width="1em" height="1em" aria-hidden="true" focusable="false"><path d="M6 4l4 4-4 4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';

    var rootLis = document.querySelectorAll(".td-sidebar-nav .ul-1 > li.with-child");
    rootLis.forEach(function(li) {
      injectToggleButton(li, caretIcon, "before", "");
    });

    var childLis = document.querySelectorAll(".td-sidebar-nav .ul-1 ul li.with-child");
    childLis.forEach(function(li) {
      injectToggleButton(li, caretIcon, "before", "child-toggle");
    });
  })();
</script>

<script>
  $(function() {
    function getSiteRootUrl() {
      const rootLink = document.querySelector("a.navbar-brand, #td-section-nav a.tree-root");
      const href = rootLink ? rootLink.getAttribute("href") : "/";
      return new URL(href || "/", window.location.href);
    }

    function buildSearchUrl(query) {
      const url = new URL("search/", getSiteRootUrl());

      if (query) {
        url.searchParams.set("q", query);
      }

      return url.toString();
    }

    const $rootSidebarItem = $("#td-section-nav > ul > li").filter(function() {
      return $(this).find('> a.tree-root, > label > a.tree-root').length > 0;
    }).first();
    const $sidebarSearchForm = $("#td-sidebar-menu form.td-sidebar__search");
    const $sidebarSearchInput = $sidebarSearchForm.find('input[name="q"]').first();

    if ($rootSidebarItem.length) {
      $rootSidebarItem.addClass("td-sidebar-root-hidden");
    }

    if (!$sidebarSearchForm.length || !$sidebarSearchInput.length) {
      return;
    }

    $sidebarSearchForm.attr("action", buildSearchUrl(""));
    $sidebarSearchForm.attr("method", "get");

    $sidebarSearchInput.attr("id", "sidebar-search-input");
    $sidebarSearchInput.attr("placeholder", "Search...");
    $sidebarSearchInput.attr("aria-label", "Search this site");

    $sidebarSearchForm.on("submit", function(event) {
      const query = ($sidebarSearchInput.val() || "").trim();

      if (!query) {
        event.preventDefault();
        $sidebarSearchInput.focus();
        return;
      }

      event.preventDefault();
      if (window.matchMedia("(max-width: 37.5em)").matches &&
          document.querySelector(".left-container.left-container--active")) {
        const toggle = document.getElementById("toggleBtnSidebarNav");
        if (toggle) toggle.click();
      }

      window.location.assign(buildSearchUrl(query));
    });

    document.addEventListener("click", function(event) {
      if (
        window.matchMedia("(max-width: 37.5em)").matches &&
        document.querySelector(".left-container.left-container--active") &&
        (event.target.closest("#td-sidebar-menu a") || event.target.closest("#td-sidebar-menu button"))
      ) {
        const toggle = document.getElementById("toggleBtnSidebarNav");
        if (toggle) toggle.click();
      }
    });
  });
</script>

