{{ if ne $ctx.section_title "false" }}

    {{ if $currentPage }}
        {{ $category := index $currentPage.Params "integrations-category" }}
        {{ if $category }}
            <h2>Related Models in <b>{{ $category }}</b></h2>
        {{ else }}
            <h2>{{ $ctx.h2_text | default "Related Models" }}</h2>
